-- Request-level idempotency for user withdrawal submissions.
-- This migration is branch-only until validated against an isolated database.
-- The request UUID is generated by the client and retained across retries.

create unique index if not exists wallet_transactions_withdraw_request_key
  on public.wallet_transactions (reference)
  where type = 'withdrawal'
    and pg_catalog.left(reference, 17) = 'withdraw_request_';

-- Replace the old five-argument function so callers must provide a request ID.
drop function if exists private.request_withdrawal(uuid, text, text, numeric, text);

create function private.request_withdrawal(
  p_user_id uuid,
  p_asset text,
  p_network text,
  p_amount numeric,
  p_address text,
  p_request_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_wallet public.wallets%rowtype;
  v_tx public.wallet_transactions%rowtype;
  v_reference text;
  v_address text := pg_catalog.btrim(coalesce(p_address, ''));
begin
  if p_user_id is null then
    raise exception 'User is required';
  end if;

  if p_request_id is null then
    raise exception 'A withdrawal request ID is required';
  end if;

  if not (
    (p_asset = 'USDT' and p_network = 'TRC-20')
    or (p_asset = 'TON' and p_network = 'TON')
  ) then
    raise exception 'Unsupported asset/network combination';
  end if;

  if p_amount is null or p_amount <= 0
     or p_amount > 1000000
     or p_amount <> pg_catalog.round(p_amount, 8) then
    raise exception 'Withdrawal amount must be positive, at most 1000000, and have no more than 8 decimal places';
  end if;

  if pg_catalog.length(v_address) < 8 or pg_catalog.length(v_address) > 200 then
    raise exception 'A valid destination address is required';
  end if;

  -- Serialize retries using the same UUID, even if the request payload differs.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_request_id::text, 0)
  );

  v_reference := 'withdraw_request_' || p_request_id::text;

  select * into v_tx
  from public.wallet_transactions wt
  where wt.type = 'withdrawal'
    and wt.reference = v_reference
  for update;

  if found then
    if v_tx.user_id <> p_user_id
       or v_tx.amount <> p_amount
       or coalesce(v_tx.metadata->>'asset', '') <> p_asset
       or coalesce(v_tx.metadata->>'network', '') <> p_network
       or coalesce(v_tx.metadata->>'destination_address', '') <> v_address
       or coalesce(v_tx.metadata->>'request_id', '') <> p_request_id::text then
      raise exception 'Request ID has already been used for a different withdrawal';
    end if;

    select * into v_wallet
    from public.wallets w
    where w.id = v_tx.wallet_id
      and w.user_id = v_tx.user_id;

    if not found then
      raise exception 'Wallet for existing withdrawal is unavailable; reconciliation required';
    end if;

    return pg_catalog.jsonb_build_object(
      'transaction_id', v_tx.id,
      'reference', v_tx.reference,
      'status', v_tx.status,
      'asset', p_asset,
      'network', p_network,
      'amount', v_tx.amount,
      'locked_balance', v_wallet.locked_balance,
      'remaining_available_balance', v_wallet.available_balance,
      'idempotent_replay', true
    );
  end if;

  select * into v_wallet
  from public.wallets w
  where w.user_id = p_user_id
    and w.asset = p_asset
    and w.network = p_network
  for update;

  if not found then
    raise exception 'Wallet is not available';
  end if;

  if v_wallet.available_balance < p_amount then
    raise exception 'Insufficient available balance';
  end if;

  insert into public.wallet_transactions(
    user_id, wallet_id, type, direction, amount, status, reference, metadata
  )
  values(
    p_user_id,
    v_wallet.id,
    'withdrawal',
    'debit',
    p_amount,
    'pending',
    v_reference,
    pg_catalog.jsonb_build_object(
      'asset', p_asset,
      'network', p_network,
      'destination_address', v_address,
      'requires_admin_review', true,
      'request_id', p_request_id::text
    )
  )
  returning * into v_tx;

  update public.wallets
  set available_balance = available_balance - p_amount,
      locked_balance = locked_balance + p_amount,
      updated_at = pg_catalog.now()
  where id = v_wallet.id
  returning * into v_wallet;

  return pg_catalog.jsonb_build_object(
    'transaction_id', v_tx.id,
    'reference', v_tx.reference,
    'status', v_tx.status,
    'asset', p_asset,
    'network', p_network,
    'amount', v_tx.amount,
    'locked_balance', v_wallet.locked_balance,
    'remaining_available_balance', v_wallet.available_balance,
    'idempotent_replay', false
  );
end;
$function$;

revoke all on function private.request_withdrawal(uuid, text, text, numeric, text, uuid)
  from public, anon, authenticated;
grant execute on function private.request_withdrawal(uuid, text, text, numeric, text, uuid)
  to service_role;
